package com.cyberyichen.bloub;
import android.content.*;
import android.content.pm.PackageManager;
import android.media.*;
import android.util.Size;
import android.view.Surface;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
/** Foreground segments, rolling motion buffers, optional shared-microphone AAC and scheduled upload. */
final class MonitorRecorder {
  private final Context context;final StorageConfig config;private final DeviceSettings settings;private final File directory;
  private final ScheduledExecutorService uploads=Executors.newSingleThreadScheduledExecutor();private final ExecutorService finalizeWork=Executors.newSingleThreadExecutor();
  private final MotionWindow events=new MotionWindow();private volatile boolean foreground,recording,manualUpload;private volatile String status="关闭",uploadStatus="未上传";private volatile long nextRetry,lastMotion;private int failures;
  private MediaRecorder recorder;private VideoCompositor renderer;private volatile MonitorAudio audio;private File partial,audioFile;private long began,beginMono;private volatile JSONObject activeConfig;
  MonitorRecorder(Context c){context=c.getApplicationContext();config=new StorageConfig(c);settings=new DeviceSettings(c);directory=new File(context.getFilesDir(),"monitor-video");directory.mkdirs();loadEvents();recover();uploads.scheduleWithFixedDelay(this::uploadTick,5,15,TimeUnit.SECONDS);}
  boolean enabled(){return settings.get().optBoolean("monitorEnabled");}boolean recording(){return recording;}void foreground(boolean value){foreground=value;}JSONObject options(){return config.get();}
  JSONObject recordingOptions(){JSONObject active=activeConfig;return active==null?options():active;}
  boolean needsMicrophone(){JSONObject c=options();return enabled()&&(c.optBoolean("recordAudio")||c.optBoolean("overlayYamnet"));}
  void pcm(short[] data,int count,long endNs){MonitorAudio sink=audio;if(recording&&sink!=null)sink.offer(data,count,endNs);}
  private File[] files(String suffix){File[] result=directory.listFiles((d,n)->n.endsWith(suffix));if(result==null)return new File[0];Arrays.sort(result,(a,b)->a.getName().compareTo(b.getName()));return result;}
  private File[] videos(){File[] result=directory.listFiles((d,n)->n.matches("[0-9]{13}-[a-f0-9]{8}\\.mp4"));if(result==null)return new File[0];Arrays.sort(result,(a,b)->a.getName().compareTo(b.getName()));return result;}
  private long bytes(){long result=0;File[] all=directory.listFiles();if(all!=null)for(File file:all)result+=file.length();return result;}
  private static JSONObject read(File file)throws Exception{try(InputStream in=new FileInputStream(file);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);return new JSONObject(out.toString("UTF-8"));}}
  private void writeMeta(File video,JSONObject data)throws Exception{File target=new File(directory,video.getName()+".json"),temp=new File(directory,video.getName()+".json.tmp");try(FileOutputStream out=new FileOutputStream(temp)){out.write(data.toString().getBytes("UTF-8"));out.getFD().sync();}if(!temp.renameTo(target))throw new IOException("录像信息保存失败");}
  private void remove(File file){file.delete();new File(directory,file.getName()+".json").delete();}
  private void loadEvents(){try{JSONObject data=new JSONObject(context.getSharedPreferences("monitor",0).getString("events","{}"));JSONArray list=data.optJSONArray("windows");if(list!=null)for(int i=0;i<list.length();i++){JSONArray span=list.getJSONArray(i);long a=span.getLong(0),b=span.getLong(1);if(b>a&&b>System.currentTimeMillis()-3600000)events.spans.add(new MotionWindow.Span(a,b));}}catch(Exception ignored){}}
  private void saveEvents(){try{JSONArray list=new JSONArray();synchronized(events){for(MotionWindow.Span span:events.spans)list.put(new JSONArray().put(span.start).put(span.end));}context.getSharedPreferences("monitor",0).edit().putString("events",new JSONObject().put("windows",list).toString()).apply();}catch(JSONException ignored){}}
  void motion(long wall){JSONObject c=recordingOptions();if(!recording||!c.optBoolean("motionOnly")||wall-lastMotion<1000||android.os.SystemClock.elapsedRealtime()-beginMono<3500)return;lastMotion=wall;events.event(wall,c.optLong("motionWindowMinutes",1));saveEvents();finalizeWork.execute(()->{promoteBuffers();prune();});status="变化录像";}
  private File[] recoveryFiles(){File[] files=directory.listFiles((d,n)->n.endsWith(".part.mp4")||n.endsWith(".mux.mp4"));return files==null?new File[0]:files;}
  private void recover(){for(File file:recoveryFiles()){MediaMetadataRetriever retriever=new MediaMetadataRetriever();try{retriever.setDataSource(file.getPath());long duration=Long.parseLong(retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION));if(duration<500)throw new IOException("Partial segment");JSONObject meta;try{meta=read(new File(directory,file.getName()+".json"));}catch(Exception missing){meta=new JSONObject().put("startedAt",Long.parseLong(file.getName().substring(0,13)));}meta.put("recovered",true).put("silent",!"yes".equals(retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_HAS_AUDIO))).put("audioMissing",!"yes".equals(retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_HAS_AUDIO))&&meta.optJSONObject("options")!=null&&meta.getJSONObject("options").optBoolean("recordAudio")).put("endedAt",meta.optLong("startedAt")+duration).put("durationMs",duration).put("uploaded",false);finalizeSegment(file,meta);}catch(Exception invalid){remove(file);}finally{retriever.release();}}for(File file:files(".audio.m4a"))file.delete();promoteBuffers();prune();}
  private void prune(){JSONObject c=options();long now=System.currentTimeMillis(),cutoff=now-c.optLong("localDays",1)*86400000;for(File file:videos())try{JSONObject meta=read(new File(directory,file.getName()+".json"));if(meta.optBoolean("uploaded")&&meta.optLong("endedAt",file.lastModified())<cutoff)remove(file);}catch(Exception ignored){}
    long bufferCutoff=now-c.optLong("motionWindowMinutes",1)*60000-c.optLong("segmentSeconds",60)*1000;for(File file:files(".buffer.mp4"))try{JSONObject meta=read(new File(directory,file.getName()+".json"));if(meta.optLong("endedAt",file.lastModified())<bufferCutoff&&events.intersection(meta.optLong("startedAt"),meta.optLong("endedAt",file.lastModified())).isEmpty())remove(file);}catch(Exception bad){if(file.lastModified()<bufferCutoff)remove(file);}events.prune(now-3600000);
  }
  synchronized Surface prepare(Size size,int baseRotation,VideoCompositor.Overlay overlay)throws Exception{
    if(recorder!=null||!foreground||!enabled())return null;prune();JSONObject c=options();long cap=c.optLong("storageMiB",1024)*1048576,reserve=c.optLong("segmentSeconds",60)*625000+8*1048576;if(bytes()+reserve>cap||new android.os.StatFs(directory.getPath()).getAvailableBytes()<reserve+16*1048576){status="本地空间已满，等待上传或清理";return null;}
    if(c.optBoolean("recordAudio")&&context.checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){status="需要麦克风权限";return null;}
    began=System.currentTimeMillis();beginMono=android.os.SystemClock.elapsedRealtime();activeConfig=new JSONObject(c.toString());String name=began+"-"+UUID.randomUUID().toString().substring(0,8);partial=new File(directory,name+".part.mp4");audioFile=new File(directory,name+".audio.m4a");recorder=new MediaRecorder();
    try{int extra=c.optBoolean("rotationEnabled")?c.optInt("rotation"):0;boolean swap=(baseRotation+extra)%180!=0;recorder.setVideoSource(MediaRecorder.VideoSource.SURFACE);recorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);recorder.setOutputFile(partial.getPath());recorder.setVideoEncoder(MediaRecorder.VideoEncoder.H264);recorder.setVideoSize(swap?size.getHeight():size.getWidth(),swap?size.getWidth():size.getHeight());recorder.setVideoFrameRate(30);recorder.setVideoEncodingBitRate(2000000);recorder.setOrientationHint(0);recorder.prepare();renderer=new VideoCompositor(recorder.getSurface(),size.getWidth(),size.getHeight(),baseRotation,extra,c.optBoolean("mirror"),overlay);if(c.optBoolean("recordAudio"))audio=new MonitorAudio(audioFile);writeMeta(partial,new JSONObject().put("startedAt",began).put("options",activeConfig));status="准备录制";return renderer.input();}catch(Exception e){release();throw e;}
  }
  synchronized void start(){if(recorder==null)return;recorder.start();if(audio!=null)audio.start(System.nanoTime());renderer.start();recording=true;status=activeConfig.optBoolean("motionOnly")&&!events.active(System.currentTimeMillis())?"等待画面变化":"正在录制";}
  int segmentSeconds(){return recordingOptions().optInt("segmentSeconds",60);}
  synchronized void finish(){MediaRecorder current=recorder;if(current==null)return;VideoCompositor gl=renderer;renderer=null;if(gl!=null)gl.close();MonitorAudio pcm=audio;audio=null;File video=partial,sound=audioFile;JSONObject snapshot=activeConfig;long started=began,ended=System.currentTimeMillis(),duration=Math.max(0,android.os.SystemClock.elapsedRealtime()-beginMono);boolean complete=false;try{if(recording){current.stop();complete=true;}}catch(RuntimeException e){status="分段未完成，稍后重试";}finally{try{current.reset();}catch(Exception ignored){}current.release();recorder=null;recording=false;partial=null;audioFile=null;}
    final boolean valid=complete&&video!=null&&video.length()>1024;finalizeWork.execute(()->{boolean hasAudio=pcm!=null&&pcm.finish();try{if(!valid){if(video!=null)remove(video);return;}File source=video;if(hasAudio){File merged=new File(directory,video.getName().replace(".part.mp4",".mux.mp4"));try{if(MovieMuxer.withAudio(video,sound,merged)){writeMeta(merged,new JSONObject().put("startedAt",started).put("options",snapshot));source=merged;remove(video);}else{merged.delete();hasAudio=false;}}catch(Exception e){merged.delete();hasAudio=false;android.util.Log.w("BloubMonitor","Audio mux",e);}}
      JSONObject meta=new JSONObject().put("schemaVersion",2).put("startedAt",started).put("endedAt",ended).put("durationMs",duration).put("silent",!hasAudio).put("audioMissing",snapshot.optBoolean("recordAudio")&&!hasAudio).put("uploaded",false).put("options",snapshot).put("annotationSource","camera_recording");finalizeSegment(source,meta);if(snapshot.optBoolean("recordAudio")&&!hasAudio)status="录音未完成，视频已保留";
    }catch(Exception e){status="录像保存失败，文件已保留";android.util.Log.w("BloubMonitor","Finalize",e);}finally{if(sound!=null)sound.delete();}});if(enabled())status=snapshot.optBoolean("motionOnly")&&!events.active(ended)?"等待画面变化":"等待下一段";else status="关闭";
  }
  private void finalizeSegment(File source,JSONObject meta)throws Exception{JSONObject c=meta.optJSONObject("options");boolean motion=c!=null&&c.optBoolean("motionOnly");if(motion){List<MotionWindow.Span> spans=events.intersection(meta.getLong("startedAt"),meta.getLong("endedAt"));if(!spans.isEmpty()){saveEventClips(source,meta,spans);remove(source);return;}File buffer=new File(directory,source.getName().replace(".part.mp4",".buffer.mp4").replace(".mux.mp4",".buffer.mp4"));writeMeta(buffer,meta);if(!source.renameTo(buffer))throw new IOException("缓冲录像保存失败");new File(directory,source.getName()+".json").delete();return;}File target=new File(directory,source.getName().replace(".part.mp4",".mp4").replace(".mux.mp4",".mp4"));writeMeta(target,meta);if(!source.renameTo(target))throw new IOException("录像保存失败");new File(directory,source.getName()+".json").delete();}
  private void saveEventClips(File source,JSONObject meta,List<MotionWindow.Span> spans)throws Exception{long start=meta.getLong("startedAt");for(MotionWindow.Span span:spans){String name=span.start+"-"+UUID.randomUUID().toString().substring(0,8)+".mp4";File target=new File(directory,name),temp=new File(directory,name+".clip");try{long offset=MovieMuxer.trim(source,temp,Math.max(0,(span.start-start)*1000),Math.max(1,(span.end-start)*1000));JSONObject data=new JSONObject(meta.toString()).put("startedAt",start+offset/1000).put("endedAt",span.end).put("durationMs",Math.max(1,span.end-start-offset/1000)).put("motionEvent",true).put("requestedStart",span.start).put("requestedEnd",span.end);writeMeta(target,data);if(!temp.renameTo(target))throw new IOException("变化录像保存失败");}finally{temp.delete();}}}
  private void promoteBuffers(){for(File file:files(".buffer.mp4"))try{JSONObject meta=read(new File(directory,file.getName()+".json"));List<MotionWindow.Span> spans=events.intersection(meta.getLong("startedAt"),meta.getLong("endedAt"));if(!spans.isEmpty()){saveEventClips(file,meta,spans);remove(file);}}catch(Exception e){android.util.Log.w("BloubMonitor","Motion buffer",e);}}
  private synchronized void release(){VideoCompositor gl=renderer;renderer=null;if(gl!=null)gl.close();MonitorAudio pcm=audio;audio=null;if(pcm!=null)pcm.finish();if(recorder!=null){recorder.release();recorder=null;}recording=false;if(partial!=null)remove(partial);if(audioFile!=null)audioFile.delete();partial=null;audioFile=null;}
  synchronized void failed(){release();status="录像配置失败，稍后重试";}
  private boolean uploadAllowed(JSONObject c){if(manualUpload||!c.optBoolean("uploadScheduleEnabled"))return true;Calendar now=Calendar.getInstance();String day=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).format(now.getTime());String complete=context.getSharedPreferences("monitor",0).getString("upload_completed."+c.optString("provider"),"");return !day.equals(complete)&&now.get(Calendar.HOUR_OF_DAY)*60+now.get(Calendar.MINUTE)>=SettingsSpec.minutes(c.optString("uploadTime","20:00"));}
  private void uploadTick(){if(!foreground)return;try{prune();JSONObject c=options();if(!c.optBoolean("autoUpload")&&!manualUpload)return;if(!uploadAllowed(c)){uploadStatus="等待定时上传";return;}if(System.currentTimeMillis()<nextRetry)return;boolean pending=false;for(File file:videos()){File sidecar=new File(directory,file.getName()+".json");JSONObject meta=sidecar.exists()?read(sidecar):new JSONObject().put("recovered",true).put("uploaded",false);if(meta.optBoolean("uploaded"))continue;pending=true;uploadStatus="正在上传";String secret=config.secret(c.getString("provider"),"secret"),token=config.secret(c.getString("provider"),"token");String key=UploadSigner.date(meta.optLong("startedAt",file.lastModified()),"yyyy-MM-dd")+"/"+file.getName();StorageUploader.upload(file,c,secret,token,key);meta.put("uploadedAt",System.currentTimeMillis()).put("objectKey",key);writeMeta(file,meta);StorageUploader.upload(sidecar,c,secret,token,key+".json");meta.put("uploaded",true);writeMeta(file,meta);failures=0;nextRetry=0;uploadStatus="上传完成";break;}if(!pending){boolean wasManual=manualUpload;manualUpload=false;if(!wasManual&&c.optBoolean("uploadScheduleEnabled"))context.getSharedPreferences("monitor",0).edit().putString("upload_completed."+c.optString("provider"),new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date())).apply();}}
    catch(Exception e){failures=Math.min(8,failures+1);nextRetry=System.currentTimeMillis()+Math.min(3600000,15000L*(1L<<failures));uploadStatus=e instanceof IOException?e.getMessage():"上传配置或凭证不可用";}}
  String info(){try{JSONArray list=new JSONArray();int pending=0;File[] all=videos();for(int i=0;i<all.length;i++){File file=all[i];JSONObject meta;try{meta=read(new File(directory,file.getName()+".json"));}catch(Exception e){meta=new JSONObject().put("uploaded",false);}if(!meta.optBoolean("uploaded"))pending++;if(i>=all.length-100)list.put(new JSONObject().put("id",file.getName()).put("bytes",file.length()).put("metadata",meta));}VideoCompositor gl=renderer;String state=gl!=null&&!gl.error().isEmpty()?gl.error():status;return new JSONObject().put("enabled",enabled()).put("recording",recording).put("status",enabled()&&!settings.get().optBoolean("camera")?"先开启相机":state).put("uploadStatus",uploadStatus).put("nextRetryAt",nextRetry).put("bytes",bytes()).put("pending",pending).put("bufferSegments",files(".buffer.mp4").length).put("renderFrames",gl==null?0:gl.frames()).put("renderFps",gl==null?0:gl.fps()).put("config",config.publicInfo()).put("profiles",config.publicProfiles()).put("videos",list).toString();}catch(Exception e){android.util.Log.w("BloubMonitor","Info",e);return "{}";}}
  InputStream open(String id)throws IOException{if(!id.matches("[0-9]{13}-[a-f0-9]{8}\\.mp4"))throw new IOException("Invalid video");return new FileInputStream(new File(directory,id));}
  synchronized boolean delete(String id){if(!id.matches("[0-9]{13}-[a-f0-9]{8}\\.mp4"))return false;File file=new File(directory,id);boolean ok=!file.exists()||file.delete();if(ok)new File(directory,id+".json").delete();return ok;}
  void configurationChanged(JSONObject previous){nextRetry=0;failures=0;manualUpload=false;JSONObject next=options();if(!previous.optString("uploadTime").equals(next.optString("uploadTime"))||(!previous.optBoolean("autoUpload")&&next.optBoolean("autoUpload")))context.getSharedPreferences("monitor",0).edit().remove("upload_completed."+next.optString("provider")).apply();uploadStatus=next.optBoolean("autoUpload")?(next.optBoolean("uploadScheduleEnabled")?"等待定时上传":"等待上传"):"未上传";}
  String testConnection(JSONObject draft)throws Exception{JSONObject c=config.preview(draft);String provider=c.getString("provider"),secret=draft.optBoolean("clearSecret")?"":draft.optString("secret"),token=draft.optBoolean("clearToken")?"":draft.optString("token");if(secret.isEmpty()&&!draft.optBoolean("clearSecret"))secret=config.secret(provider,"secret");if(token.isEmpty()&&!draft.optBoolean("clearToken"))token=config.secret(provider,"token");try{return StorageUploader.test(context,c,secret,token).toString();}catch(java.net.UnknownHostException e){throw new IOException("地址无法解析");}catch(java.net.SocketTimeoutException e){throw new IOException("连接超时");}catch(javax.net.ssl.SSLException e){throw new IOException("HTTPS 验证失败");}catch(java.net.ConnectException e){throw new IOException("无法连接服务");}}
  void retry(){nextRetry=0;failures=0;manualUpload=true;uploadStatus="等待上传";}
  void destroy(){foreground=false;finish();uploads.shutdownNow();finalizeWork.shutdown();}
}
